import * as React from "react";
import { cn } from "~lib/cn";

export function Kbd({ className, ...props }: React.ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd"
      className={cn(
        "inline-flex h-5 min-w-5 items-center justify-center rounded-[5px] border border-b-2 border-border bg-sunken px-1 font-mono text-[0.6875rem] font-medium text-muted",
        className,
      )}
      {...props}
    />
  );
}
